import{_ as o,a0 as u,w as s,s as l,ao as d,I as r,x as e,a1 as p,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"如何将 Ubuntu14.04 安全的升级到14.10 | LCTT x X-CMD","titleTemplate":false,"description":"如何将 Ubuntu14.04 安全的升级到14.10 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何将 Ubuntu14.04 安全的升级到14.10 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何将 Ubuntu14.04 安全的升级到14.10 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141024 How To Upgrade Ubuntu 14.04 Trusty To Ubuntu 14.10 Utopic","title":"如何将 Ubuntu14.04 安全的升级到14.10","tag":"201411","desc":""},"relativePath":"201411/20141024 How To Upgrade Ubuntu 14.04 Trusty To Ubuntu 14.10 Utopic.md","filePath":"[post].md"}'),i={name:"201411/20141024 How To Upgrade Ubuntu 14.04 Trusty To Ubuntu 14.10 Utopic.md"};function g(m,t,b,c,h,T){const n=u("Link");return s(),l("div",null,[t[11]||(t[11]=d(`<h1 id="如何将-ubuntu14-04-安全的升级到14-10" tabindex="-1">如何将 Ubuntu14.04 安全的升级到14.10 <a class="header-anchor" href="#如何将-ubuntu14-04-安全的升级到14-10" aria-label="Permalink to “如何将 Ubuntu14.04 安全的升级到14.10”">​</a></h1><p>如果想从Ubuntu14.04/13.10/13.04/12.10/12.04或者更老的版本升级到14.10，只要遵循下面给出的步骤。注意，你不能直接从13.10升级到14.10。你应该先将13.10升级到14.04在从14.04升级到14.10。下面是详细步骤。</p><p>下面的步骤不仅能用于14.10，也兼容于一些像Lubuntu14.10，Kubuntu14.10和Xubuntu14.10等的Ubuntu衍生版本</p><p><strong>重要</strong>：在升级之前，保险起见，不要忘了将你的数据在U盘或外部硬盘上保存一下。</p><h3 id="桌面升级" tabindex="-1">桌面升级 <a class="header-anchor" href="#桌面升级" aria-label="Permalink to “桌面升级”">​</a></h3><p>在升级之前，我们要先更新系统。打开终端输入以下命令</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade
</code></pre><p>上面的命令会下载安装最新的包。</p><p>重启你的电脑以完成更新。</p><p>然后输入下面的命令来升级到新的可获得的版本</p><pre><code>sudo update-manager -d
</code></pre><p>软件更新器会出现并且搜索新的发行版。</p><p>几秒钟之后，你会在屏幕中看到如下字样：<strong>ubuntu14.10现在可以获得(你现在是14.04系统)</strong>。点击升级按钮开始升级。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Software-Updater_001.png" alt=""></p><p>软件更新器会提示你确定更新。点击开始更新开始安装14.10</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Release-Notes_002.png" alt=""></p><p><strong>请注意</strong>：这是beta版本。不要在生产用的机器上安装。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Distribution-Upgrade_003.png" alt=""></p><p>几分钟之后，软件更新器会提醒你一些将被移除的和将被安装的软件包的详细信息。点击<strong>开始升级</strong>继续。确保你更新时在稳定的网络下。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Untitled-window_004.png" alt=""></p><p>现在，更新程序会开始获取新的软件包。获取速度取决于你的网速。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Distribution-Upgrade_005.png" alt=""></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Distribution-Upgrade_001.png" alt=""></p><p>之后，你会被询问是否移除不必要的应用程序。最后，点击<strong>重启</strong>来完成整个升级过程。</p><p>这时侯，恭喜你已经成功的升级到了ubuntu14.10</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/10/Details_002.png" alt=""></p><p>你可以开始使用新的ubuntu版本了。</p><h3 id="服务器升级" tabindex="-1">服务器升级 <a class="header-anchor" href="#服务器升级" aria-label="Permalink to “服务器升级”">​</a></h3><p>从ubuntu14.04的服务器升级到14.10的服务器，采用下面的步骤。</p><p>安装update-manager-core 这个包如果之前没唷安装的话：</p><pre><code>sudo apt-get install update-manager-core
</code></pre><p>编辑 /etc/update-manager/release-upgrades这个文件。</p><pre><code>sudo nano /etc/update-manager/release-upgrades
</code></pre><p>像下面那样设置Prompt=normal或者Prompt=lts</p><pre><code># Default behavior for the release upgrader.

[DEFAULT]
# Default prompting behavior, valid options:
#
#  never  - Never check for a new release.
#  normal - Check to see if a new release is available.  If more than one new
#           release is found, the release upgrader will attempt to upgrade to
#           the release that immediately succeeds the currently-running
#           release.
#  lts    - Check to see if a new LTS release is available.  The upgrader
#           will attempt to upgrade to the first LTS release available after
#           the currently-running one.  Note that this option should not be
#           used if the currently-running release is not itself an LTS
#           release, since in that case the upgrader won&#39;t be able to
#           determine if a newer release is available.
Prompt=normal
</code></pre><p>现在可以通过下面的命令来更新你的服务系统了。</p><pre><code>sudo do-release-upgrade -d
</code></pre><p>直到屏幕提示你已完成。</p><hr>`,39)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),p(n,{href:"http://www.unixmen.com/upgrade-ubuntu-14-04-trusty-ubuntu-14-10-utopic/"},{default:a(()=>[...t[0]||(t[0]=[e("http://www.unixmen.com/upgrade-ubuntu-14-04-trusty-ubuntu-14-10-utopic/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("作者：SK 译者：",-1)),p(n,{href:"https://github.com/johnhoow"},{default:a(()=>[...t[2]||(t[2]=[e("johnhoow",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),p(n,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const _=o(i,[["render",g]]);export{U as __pageData,_ as default};
